create table if not exists doctors (id uuid primary key default gen_random_uuid(), name text not null, email text not null unique, role text not null check (role in ('admin','doctor')), active boolean not null default true);
create table if not exists appointments (id uuid primary key default gen_random_uuid(), doctor_id uuid not null references doctors(id), patient_name text not null, patient_email text not null, patient_phone text not null, service text not null, starts_at timestamptz not null, status text not null default 'booked' check (status in ('booked','cancelled')), cancelled_at timestamptz, created_at timestamptz not null default now());
create unique index if not exists appointments_active_slot_unique on appointments(doctor_id, starts_at) where status='booked';
